CREATE OR REPLACE FUNCTION advance_chat_activity() RETURNS trigger AS $$
BEGIN
  IF OLD.status = 'generating' AND NEW.status IN ('done', 'error', 'canceled')
     AND NEW.role = 'assistant' THEN
    INSERT INTO chat_activities (chat_id, revision) VALUES (NEW.chat_id, 1)
    ON CONFLICT (chat_id) DO UPDATE SET revision = chat_activities.revision + 1;
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;
